package com.company.tpm.ui;import com.company.tpm.dashboard.DashboardService;import com.vaadin.flow.component.html.*;import com.vaadin.flow.component.orderedlayout.*;import com.vaadin.flow.router.*;import jakarta.annotation.security.PermitAll;
@Route(value="",layout=MainLayout.class)@PageTitle("Dashboard | TPM")@PermitAll public class DashboardView extends VerticalLayout{public DashboardView(DashboardService service){var s=service.summary();add(new H1("Training dashboard"));var row=new HorizontalLayout();row.setWidthFull();row.add(card("Active employees",s.activeEmployees()),card("Active courses",s.activeCourses()),card("Tomorrow's sessions",s.upcomingSessions()));add(row);}private Div card(String label,long value){var d=new Div(new H2(String.valueOf(value)),new Span(label));d.addClassName("glass-card");return d;}}
